    try { Field f = c.getDeclaredField(field); f.setAccessible(true); if (Modifier.isStatic(f.getModifiers()) && !Modifier.isFinal(f.getModifiers())) f.set(null, value); } catch (NoSuchFieldException ignored) { }
  }
