public class Solution {
    static int[] boxes = {12, 30, 7, 25, 18};
    static int item = 3;
    static char op = '+';
    static int qty = 20;

    public static void main(String[] args) {
        int i = item - 1;
        int before = boxes[i];
        switch (op) {
            case '+': boxes[i] += qty; break;
            case '-': boxes[i] -= qty; break;
            case '=': boxes[i] = qty; break;
        }
        System.out.println("Item " + item + ": " + before + " -> " + boxes[i]);
    }
}

